    /// A football (soccer) competition on ESPN; cups run a little longer.
    private static func soc(_ path: String, _ name: String, _ short: String, _ words: [String], regions: Set<String> = [],
                            color: UInt32 = 0xFF2A2F3A, women: Bool = false, national: Bool = false) -> League {
        let cup = ["cup", "copa", "pokal", "taca", "coupe"].contains { path.contains($0) }
        return League(id: "soccer/" + path, sport: .football, name: name, short: short, espnPath: "soccer/" + path,
                      guideWords: words, regions: regions, minutes: cup ? 125 : 115, color: color,
                      national: national, women: women)
    }

    /// A rugby union competition on ESPN.
    private static func rug(_ id: String, _ name: String, _ short: String, _ words: [String], regions: Set<String> = [],
                            color: UInt32 = 0xFF1B4332, women: Bool = false, national: Bool = false) -> League {
        League(id: "rugby/" + id, sport: .rugby, name: name, short: short, espnPath: "rugby/" + id,
               guideWords: words, regions: regions, minutes: 110, color: color, national: national, women: women)
    }
